// Implementation of ray-AABB intersection using the slab method
// Optimized using precomputed inverse direction and direction signs

float tmin = min_t;
float tmax = max_t;

for (int i = 0; i < 3; i++) {
    const float origin = ray_org[i];
    const float inv_dir = ray_inv_dir[i];
    const int sign = ray_dir_sign[i];

    float t1 = (bmin[sign][i] - origin) * inv_dir;
    float t2 = (bmax[1-sign][i] - origin) * inv_dir;

    if (t1 > tmin) tmin = t1;
    if (t2 < tmax) tmax = t2;

    if (tmin > tmax) {
        return false;
    }
}

*tminOut = tmin;
*tmaxOut = tmax;
return true;

